def checked(source, name):
    if type(source) is not str: raise ValueError("Popup lifetime requires text")
    source = source.replace("\r\n", "\n")
    if hashlib.sha256(source.encode()).hexdigest() != PINS[name]: raise ValueError("Popup lifetime source/version/order mismatch")
    return source
def transform(source, name):
    source = checked(source, name)
    for old, new, count in EDITS[name]:
        if source.count(old) != count: raise ValueError("Popup lifetime anchor drift")
        source = source.replace(old, new)
    return source
def reverse(source, name):
    for old, new, count in reversed(EDITS[name]):
        if source.count(new) != count: raise ValueError("Popup lifetime output drift")
        source = source.replace(new, old)
    return checked(source, name)
def transform_sources(sources):
    if type(sources) is not dict or not PINS.keys() <= sources.keys(): raise ValueError("Popup lifetime resources missing")
    result = dict(sources)
    for name in PINS: result[name] = transform(result[name], name)
    return result
